import jakarta.persistence.*;
import org.springframework.data.jpa.repository.JpaRepository;

// JPA annotations define the structure
@Entity  // JPA specification annotation
@Table(name = "orders")
public class Order {
    @Id  // JPA defines this as primary key
    @GeneratedValue(strategy = GenerationType.IDENTITY)  // JPA strategy
    private Long id;

    private String customerName;
    private Double totalAmount;

    @ManyToOne(fetch = FetchType.LAZY)  // JPA relationship
    @JoinColumn(name = "customer_id")  // JPA join definition
    private Customer customer;
}

// Spring Data JPA repository - uses Hibernate underneath
interface OrderRepository extends JpaRepository<Order, Long> {
    // Method name converted to JPQL by Spring Data, executed by Hibernate
    List<Order> findByCustomerName(String name);
}

// JDBC approach - verbose and manual
public List<Order> findOrdersByCustomer(String customerName) {
    var orders = new ArrayList<Order>();
    var sql = "SELECT id, customer_name, total FROM orders WHERE customer_name = ?";
    try (var conn = dataSource.getConnection();
         var stmt = conn.prepareStatement(sql)) {
        stmt.setString(1, customerName);
        var rs = stmt.executeQuery();
        while (rs.next()) {  // Manual mapping
            var order = new Order();
            order.setId(rs.getLong("id"));
            order.setCustomerName(rs.getString("customer_name"));
            order.setTotal(rs.getDouble("total"));
            orders.add(order);
        }
    } catch (SQLException e) {
        throw new RuntimeException(e);
    }
    return orders;
}

