// Java 17 + Spring Data JDBC: repository like JPA, but predictable
import org.springframework.data.annotation.Id;
import org.springframework.data.repository.ListCrudRepository;

class Order {                 // plain class, Spring Data JDBC annotations
    @Id private Long id;
    private String status;
    // getters / setters
}

interface OrderRepository extends ListCrudRepository<Order, Long> { }

// Usage:
Order order = orderRepository.findById(1L).orElseThrow(); // one SELECT, eager
order.setStatus("SHIPPED");
// Nothing persists yet — there is NO dirty checking:
orderRepository.save(order); // you must call save() to fire the UPDATE
```
*Unlike JPA, modifying the entity does nothing until you explicitly call `save()` — no hidden flush.*
